public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }
    int hash = 1;
    for (int i = 0; i < array.length; i++) {
        long value = array[i];
        hash = 31 * hash + (int) (value ^ (value >>> 32));
    }
    return hash;
}

