private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        return null;
    }
    TreeNode<T> left = node.left;
    if (left == null) {
        return node; // nothing to rotate
    }
    TreeNode<T> rightOfLeft = left.right;

    // perform rotation
    left.right = node;
    node.left = rightOfLeft;

    // Update parents
    left.parent = node.parent;
    node.parent = left;
    if (rightOfLeft != null) {
        rightOfLeft.parent = node;
    }

    // Adjust pointer from old parent to new parent
    if (left.parent != null) {
        if (left.parent.left == node) {
            left.parent.left = left;
        } else if (left.parent.right == node) {
            left.parent.right = left;
        }
    }

    return left;
}

