public static void addToClassPath(Vector<URL> cpV, String dir) {
    if (cpV == null) {
        throw new IllegalArgumentException("classpath vector cannot be null");
    }
    if (dir == null || dir.isEmpty()) {
        return;
    }
    File folder = new File(dir);
    if (!folder.exists() || !folder.isDirectory()) {
        return;
    }
    File[] files = folder.listFiles();
    if (files == null) {
        return;
    }
    for (File f : files) {
        if (f.isFile() && f.getName().toLowerCase().endsWith(".jar")) {
            try {
                cpV.add(f.toURI().toURL());
            } catch (MalformedURLException e) {
                // log the issue but continue processing other files
                System.err.println("Failed to convert file to URL: " + f);
            }
        }
    }
}

public static void addToClassPath(Vector<URL> cpV,String dir){
    if(cpV == null || dir == null){
        throw new IllegalArgumentException("Classpath vector and directory must not be null");
    }
    File folder = new File(dir);
    if(!folder.exists()){
        throw new IllegalArgumentException("Directory does not exist: "+dir);
    }
    if(!folder.isDirectory()){
        throw new IllegalArgumentException("Provided path is not a directory: "+dir);
    }
    File[] files = folder.listFiles(new FilenameFilter() {
        @Override
        public boolean accept(File dir, String name) {
            return name.toLowerCase().endsWith(".jar");
        }
    });
    if(files == null){
        return;
    }
    for(File f : files){
        try {
            cpV.add(f.toURI().toURL());
        } catch (MalformedURLException e) {
            // ignore malformed URLs
        }
    }
}

