public String format(LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        String level = event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN";
        long timeMillis = event.getTimeMillis();
        java.util.Date date = new java.util.Date(timeMillis);
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        String timestamp = sdf.format(date);
        Object msgObj = event.getMessage();
        String message = msgObj != null ? msgObj.toString() : "";
        return "[" + level + "] " + timestamp + " - " + message;
    } catch (Exception e) {
        return "Error formatting event: " + e.getMessage();
    }
}

