private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    int length = headerPart.length();
    if (end < 0 || end >= length) {
        throw new IllegalArgumentException("end index out of bounds");
    }
    for (int i = end; i < length - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    // If the string ends with a single '\r', return its index
    if (end <= length - 1 && headerPart.charAt(length - 1) == '\r') {
        return length - 1;
    }
    // No CRLF found
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    if(headerPart == null){
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    if(end < 0 || end >= headerPart.length()){
        throw new IllegalArgumentException("end index out of bounds");
    }
    int crlfIndex = headerPart.indexOf("\r\n", end);
    return crlfIndex; // returns -1 if not found
}

private int parseEndOfLine(String headerPart,int end){
    if(headerPart==null||headerPart.isEmpty()||end<0){
        return -1;
    }
    int len = headerPart.length();
    int idx = end;
    while(idx < len-1){
        if(headerPart.charAt(idx)=='\r' && headerPart.charAt(idx+1)=='\n'){
            return idx;
        }
        idx++;
    }
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    if(headerPart == null || headerPart.isEmpty()){
        return -1;
    }
    if(end < 0){
        end = 0;
    }
    int length = headerPart.length();
    for(int i = end; i < length - 1; i++){
        if(headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart cannot be null.");
    }
    int length = headerPart.length();
    if (end < 0) {
        throw new IndexOutOfBoundsException("The *end* index must be >= 0.");
    }
    for (int i = end; i < length - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            // Return the index of the first character in the CRLF sequence.
            return i;
        }
    }
    // If the CRLF was not found, return -1 to indicate failure.
    return -1;
}

