    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file cannot be null");
    }
    // If the file is a directory, schedule all its children first
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }
    try {
        file.deleteOnExit();
    } catch (Exception e) {
        // Wrap any unexpected exception in an IOException
        throw new IOException("Failed to schedule deletion of " + file, e);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }
    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    // Helper method to register files for deletion in reverse order (children first)
    java.util.Deque<File> stack = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File current = stack.pop();
        if (current.isDirectory()) {
            File[] files = current.listFiles();
            if (files == null) {
                throw new IOException("Unable to list directory contents for: " + current);
            }
            for (File child : files) {
                stack.push(child);
            }
        }
        try {
            current.deleteOnExit();
        } catch (SecurityException se) {
            throw new IOException("Unable to schedule delete on exit for: " + current, se);
        }
    }
}

