            if (v == null) {
                throw new RuntimeException("Failed to add vertex to graph");
            }
            leftVertices.add(v);
            resultMap.put("L" + i, v);
        }

        // Create the right partition vertices
        List<V> rightVertices = new ArrayList<>(rightSize);
        for (int j = 0; j < rightSize; j++) {
            V v = target.addVertex();
            if (v == null) {
                throw new RuntimeException("Failed to add vertex to graph");
            }
            rightVertices.add(v);
            resultMap.put("R" + j, v);
        }

        // Add all possible edges between the two partitions
        for (V u : leftVertices) {
            for (V v : rightVertices) {
                if (target.addEdge(u, v) == null) {
                    // Some graph implementations might return null if edge already exists;
                    // ignore or handle accordingly
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Error generating complete bipartite graph", e);
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if(target == null || resultMap == null) return;
    // Ensure all vertices are added to the graph
    for(V v : resultMap.values()){
        try{
            target.addVertex(v);
        }catch(Exception ignored){}
    }
    // Build a complete bipartite graph by dividing the vertices into two sets
    List<V> allVertices = new ArrayList<>(resultMap.values());
    int total = allVertices.size();
    if(total < 2) return; // nothing to add
    int split = total / 2; // first half vs second half
    for(int i = 0; i < split; i++){
        V u = allVertices.get(i);
        for(int j = split; j < total; j++){
            V v = allVertices.get(j);
            try{
                target.addEdge(u, v);
            }catch(Exception ignored){}
        }
    }
}

