    }
    // Compute the serialized size of the message using the provided schema.
    int size = schema.getSerializedSize(message);
    // Write the size as a varint prefix.
    CodedOutputStream codedOut = CodedOutputStream.newInstance(out);
    codedOut.writeInt32NoTag(size);
