public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type owner = pt.getOwnerType();
    Class<?> rawType;
    try {
        rawType = (Class<?>) pt.getRawType();
    } catch (ClassCastException e) {
        return null;
    }

    // Build a map from type variables of rawType to actual types as seen in targetType
    Map<TypeVariable<?>, Type> typeVarMap = new HashMap<>();
    Class<?> curr = targetType;
    while (curr != null) {
        Type genericSuper = curr.getGenericSuperclass();
        if (genericSuper instanceof ParameterizedType) {
            ParameterizedType pSuper = (ParameterizedType) genericSuper;
            Class<?> superRaw = (Class<?>) pSuper.getRawType();
            if (superRaw.equals(rawType)) {
                TypeVariable<?>[] vars = rawType.getTypeParameters();
                Type[] args = pSuper.getActualTypeArguments();
                for (int i = 0; i < vars.length; i++) {
                    typeVarMap.put(vars[i], args[i]);
                }
                break;
            }
        }
        for (Type iface : curr.getGenericInterfaces()) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType pIface = (ParameterizedType) iface;
                Class<?> ifaceRaw = (Class<?>) pIface.getRawType();
                if (ifaceRaw.equals(rawType)) {
                    TypeVariable<?>[] vars = rawType.getTypeParameters();
                    Type[] args = pIface.getActualTypeArguments();
                    for (int i = 0; i < vars.length; i++) {
                        typeVarMap.put(vars[i], args[i]);
                    }
                    break;
                }
            }
        }
        if (!typeVarMap.isEmpty()) {
            break;
        }
        curr = curr.getSuperclass();
    }

    if (typeVarMap.isEmpty()) {
        return null;
    }

    Type[] actualArgs = pt.getActualTypeArguments();
    Class<?>[] resolved = new Class<?>[actualArgs.length];
    for (int i = 0; i < actualArgs.length; i++) {
        Type t = actualArgs[i];
        try {
            if (t instanceof Class<?>) {
                resolved[i] = (Class<?>) t;
            } else if (t instanceof ParameterizedType) {
                resolved[i] = (Class<?>) ((ParameterizedType) t).getRawType();
            } else if (t instanceof TypeVariable<?>) {
                Type mapped = typeVarMap.get(t);
                if (mapped instanceof Class<?>) {
                    resolved[i] = (Class<?>) mapped;
                } else if (mapped instanceof ParameterizedType) {
                    resolved[i] = (Class<?>) ((ParameterizedType) mapped).getRawType();
                } else {
                    return null; // cannot resolve to a concrete Class
                }
            } else {
                return null; // unsupported type for resolution
            }
        } catch (Exception e) {
            return null;
        }
    }
    return resolved;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    try {
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }
        ParameterizedType paramType = (ParameterizedType) genericType;
        Type[] typeArgs = paramType.getActualTypeArguments();
        Class<?>[] result = new Class<?>[typeArgs.length];
        Map<TypeVariable<?>, Type> typeVarMap = buildTypeVariableMap(targetType, new HashMap<>());
        for (int i = 0; i < typeArgs.length; i++) {
            Class<?> resolved = resolveGenericType(typeArgs[i], typeVarMap);
            if (resolved == null) {
                return null;
            }
            result[i] = resolved;
        }
        return result;
    } catch (Exception e) {
        return null;
    }
}

private static Class<?> resolveGenericType(Type type, Map<TypeVariable<?>, Type> map) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof WildcardType) {
        return null;
    }
    if (type instanceof TypeVariable<?>) {
        Type resolved = map.get(type);
        if (resolved == null) {
            return null;
        }
        if (resolved instanceof Class<?>) {
            return (Class<?>) resolved;
        }
        if (resolved instanceof ParameterizedType) {
            return (Class<?>) ((ParameterizedType) resolved).getRawType();
        }
        // If resolved is still a TypeVariable, return null
        return null;
    }
    if (type instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) type).getRawType();
    }
    return null;
}

private static Map<TypeVariable<?>, Type> buildTypeVariableMap(Type type, Map<TypeVariable<?>, Type> map) {
    if (type instanceof Class<?>) {
        Class<?> cls = (Class<?>) type;
        // Process superclass
        Type superType = cls.getGenericSuperclass();
        if (superType != null) {
            buildTypeVariableMap(superType, map);
        }
        // Process interfaces
        for (Type iface : cls.getGenericInterfaces()) {
            buildTypeVariableMap(iface, map);
        }
    } else if (type instanceof ParameterizedType) {
        ParameterizedType pType = (ParameterizedType) type;
        Class<?> raw = (Class<?>) pType.getRawType();
        TypeVariable<?>[] vars = raw.getTypeParameters();
        Type[] args = pType.getActualTypeArguments();
        for (int i = 0; i < vars.length; i++) {
            map.put(vars[i], args[i]);
        }
        // Recurse into superclass and interfaces of raw type
        buildTypeVariableMap(raw, map);
    }
    return map;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        throw new IllegalArgumentException("genericType and targetType must not be null");
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pType = (ParameterizedType) genericType;
    Class<?> raw = (Class<?>) pType.getRawType();
    if (!raw.isAssignableFrom(targetType)) {
        return null;
    }
    Type[] rawArgs = pType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[rawArgs.length];

    // Build a map from type variables to actual types for targetType relative to raw
    java.util.Map<TypeVariable<?>, Type> typeVarMap = new java.util.HashMap<>();
    Class<?> current = targetType;
    while (current != null && current != raw) {
        // Superclass
        Type superT = current.getGenericSuperclass();
        if (superT instanceof ParameterizedType) {
            ParameterizedType superPT = (ParameterizedType) superT;
            Class<?> superRaw = (Class<?>) superPT.getRawType();
            TypeVariable<?>[] superVars = superRaw.getTypeParameters();
            Type[] superArgs = superPT.getActualTypeArguments();
            for (int i = 0; i < superVars.length; i++) {
                if (!typeVarMap.containsKey(superVars[i])) {
                    typeVarMap.put(superVars[i], superArgs[i]);
                }
            }
        }
        // Interfaces
        Type[] interfaces = current.getGenericInterfaces();
        for (Type iface : interfaces) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType ifacePT = (ParameterizedType) iface;
                Class<?> ifaceRaw = (Class<?>) ifacePT.getRawType();
                TypeVariable<?>[] ifaceVars = ifaceRaw.getTypeParameters();
                Type[] ifaceArgs = ifacePT.getActualTypeArguments();
                for (int i = 0; i < ifaceVars.length; i++) {
                    if (!typeVarMap.containsKey(ifaceVars[i])) {
                        typeVarMap.put(ifaceVars[i], ifaceArgs[i]);
                    }
                }
            }
        }
        current = current.getSuperclass();
    }

    // Resolve each argument to a concrete Class
    for (int i = 0; i < rawArgs.length; i++) {
        Type arg = rawArgs[i];
        try {
            Class<?> resolved = null;
            while (arg != null) {
                if (arg instanceof Class<?>) {
                    resolved = (Class<?>) arg;
                    break;
                } else if (arg instanceof TypeVariable<?>) {
                    arg = typeVarMap.get((TypeVariable<?>) arg);
                    if (arg == null) {
                        break;
                    }
                } else if (arg instanceof ParameterizedType) {
                    resolved = (Class<?>) ((ParameterizedType) arg).getRawType();
                    break;
                } else {
                    // Unsupported type (Wildcard, GenericArray, etc.)
                    break;
                }
            }
            if (resolved == null) {
                return null;
            }
            result[i] = resolved;
        } catch (ClassCastException | IllegalArgumentException e) {
            return null;
        }
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType){
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];

    // Map to store type variable bindings from targetType hierarchy
    Map<TypeVariable<?>, Type> varMap = new HashMap<>();

    Class<?> cur = targetType;
    while (cur != null && cur != Object.class) {
        // Superclass mapping
        Type superT = cur.getGenericSuperclass();
        if (superT instanceof ParameterizedType) {
            ParameterizedType spt = (ParameterizedType) superT;
            TypeVariable<?>[] vars = cur.getSuperclass().getTypeParameters();
            Type[] actuals = spt.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                varMap.put(vars[i], actuals[i]);
            }
        }
        // Interface mappings
        for (Type iface : cur.getGenericInterfaces()) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType ipt = (ParameterizedType) iface;
                Class<?> raw = (Class<?>) ipt.getRawType();
                TypeVariable<?>[] vars = raw.getTypeParameters();
                Type[] actuals = ipt.getActualTypeArguments();
                for (int i = 0; i < vars.length; i++) {
                    varMap.put(vars[i], actuals[i]);
                }
            }
        }
        cur = cur.getSuperclass();
    }

    for (int i = 0; i < args.length; i++) {
        Type t = args[i];
        Class<?> resolved = null;
        // Resolve type variables through the map
        int maxDepth = 10;
        while (t instanceof TypeVariable && maxDepth-- > 0) {
            TypeVariable<?> tv = (TypeVariable<?>) t;
            t = varMap.get(tv);
            if (t == null) {
                break;
            }
        }
        if (t instanceof Class) {
            resolved = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) t).getRawType();
            if (raw instanceof Class) {
                resolved = (Class<?>) raw;
            }
        } else if (t instanceof WildcardType) {
            WildcardType wt = (WildcardType) t;
            if (wt.getUpperBounds() != null && wt.getUpperBounds().length > 0) {
                Type ub = wt.getUpperBounds()[0];
                if (ub instanceof Class) {
                    resolved = (Class<?>) ub;
                } else if (ub instanceof ParameterizedType) {
                    Type raw = ((ParameterizedType) ub).getRawType();
                    if (raw instanceof Class) {
                        resolved = (Class<?>) raw;
                    }
                }
            }
        }
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

