protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    // Validate input
    if (start > end) {
        return ranges;
    }
    if (FETCH_DATA_DURATION <= 0) {
        // Single range if duration is non-positive
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    long current = start;
    while (current <= end) {
        long next = Math.min(current + FETCH_DATA_DURATION - 1, end);
        ranges.add(new TimeRange(current, next));
        if (next == Long.MAX_VALUE) {
            break; // avoid overflow
        }
        current = next + 1;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }
    if (start > end) {
        long tmp = start;
        start = end;
        end = tmp;
    }
    long current = start;
    while (current < end) {
        long next = current + FETCH_DATA_DURATION;
        if (next <= 0 || next > end) { // handle overflow or surpassing end
            next = end;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (FETCH_DATA_DURATION <= 0 || start >= end){
        return ranges;
    }
    long current = start;
    while (current < end){
        long next = current + FETCH_DATA_DURATION;
        if (next > end || next <= current){
            next = end;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
