}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    try {
        if (start < 0 || end <= start) {
            return ranges;
        }
        long current = start;
        while (current < end) {
            long nextEnd;
            // Prevent overflow when adding FETCH_DATA_DURATION
            if (FETCH_DATA_DURATION > 0 && current <= Long.MAX_VALUE - FETCH_DATA_DURATION) {
                nextEnd = current + FETCH_DATA_DURATION;
            } else {
                nextEnd = end;
            }
            if (nextEnd > end) {
                nextEnd = end;
            }
            ranges.add(new TimeRange(current, nextEnd));
            current = nextEnd;
        }
    } catch (Exception ex) {
        // Log or handle unexpected errors if a logger is available
        // logger.error("Error building time ranges", ex);
        throw new RuntimeException("Failed to build time ranges", ex);
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    if(start < 0 || end < start){
        throw new IllegalArgumentException("Invalid time range: start=" + start + ", end=" + end);
    }
    List<TimeRange> ranges = new ArrayList<>();
    long rangeSize = FETCH_DATA_DURATION; // assume this constant is defined elsewhere
    long current = start;
    while(current + rangeSize < end){
        ranges.add(new TimeRange(current, current + rangeSize));
        current += rangeSize;
    }
    ranges.add(new TimeRange(current, end));
    return ranges;
}

