    }
    int strLen = str.length();
    int start = index < 0 ? 0 : index;
    int end = start + len;
    if (end > strLen) {
        end = strLen;
    }
    if (start >= end) {
        return 0;
    }

    int size = 0;
    for (int i = start; i < end; ) {
        char ch = str.charAt(i);
        int cp = ch;
        // Handle surrogate pairs
        if (Character.isHighSurrogate(ch) && i + 1 < end) {
            char low = str.charAt(i + 1);
            if (Character.isLowSurrogate(low)) {
                cp = Character.toCodePoint(ch, low);
                i += 2;
            } else {
                i += 1; // unmatched high surrogate treated as single unit
            }
        } else {
            i += 1;
        }

        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

