public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new java.util.ArrayList<>();
    if (u == null) {
        return result;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return result;
    }
    boolean isAbsolute = path.startsWith("/");
    String[] parts = path.split("/");
    int startIndex = isAbsolute ? 1 : 0;
    for (int i = startIndex; i < parts.length; i++) {
        String segment = parts[i];
        if (decode) {
            try {
                segment = java.net.URLDecoder.decode(segment, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; rethrow as unchecked
                throw new RuntimeException(e);
            }
        }
        result.add(new PathSegmentImpl(segment));
    }
    return result;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    java.util.List<PathSegmentImpl> result = new java.util.ArrayList<>();
    if (u == null) {
        return result;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return result;
    }
    // Ignore leading '/' for absolute paths
    int startIdx = rawPath.startsWith("/") ? 1 : 0;
    int i = startIdx;
    while (i <= rawPath.length()) {
        int slashIdx = rawPath.indexOf('/', i);
        if (slashIdx == -1) {
            slashIdx = rawPath.length();
        }
        String rawSegment = rawPath.substring(startIdx, slashIdx);
        startIdx = slashIdx + 1; // move past the slash
        // Skip empty segments that may result from consecutive slashes or trailing slash
        if (rawSegment.isEmpty()) {
            i = startIdx;
            continue;
        }
        String decodedSegment = rawSegment;
        if (decode) {
            try {
                decodedSegment = java.net.URLDecoder.decode(rawSegment, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        result.add(new PathSegmentImpl(rawSegment, decodedSegment));
        i = startIdx;
    }
    return result;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new java.util.ArrayList<>();
    if (u == null) {
        return result;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return result;
    }
    int index = 0;
    // Ignore leading '/' for absolute paths
    if (path.startsWith("/")) {
        index = 1;
    }
    while (index <= path.length()) {
        int slash = path.indexOf('/', index);
        String segment;
        if (slash == -1) {
            segment = path.substring(index);
            index = path.length() + 1; // exit loop
        } else {
            segment = path.substring(index, slash);
            index = slash + 1;
        }
        if (segment.isEmpty()) {
            continue; // skip empty segments
        }
        String value;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(segment, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported, wrap in runtime exception for safety
                throw new RuntimeException(e);
            }
        } else {
            value = segment;
        }
        result.add(new PathSegmentImpl(value));
    }
    return result;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    String[] rawSegments = path.split("/", -1);
    int startIdx = 0;
    if (rawSegments.length > 0 && rawSegments[0].isEmpty()) {
        startIdx = 1;
    }
    for (int i = startIdx; i < rawSegments.length; i++) {
        String seg = rawSegments[i];
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(seg, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(seg));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new NullPointerException("URI must not be null");
    }
    String rawPath = u.getRawPath();
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // ignore leading '/' if present
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    String[] parts = rawPath.split("/", -1); // keep empty segments
    for (String part : parts) {
        String decoded = part;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        // create PathSegmentImpl; constructor order may vary, use decoded first, encoded second
        segments.add(new PathSegmentImpl(decoded, part));
    }
    return segments;
}

