public Logger exists(String name){
    try {
        if (name == null || name.isEmpty()) {
            return null;
        }
        java.util.logging.LogManager lm = java.util.logging.LogManager.getLogManager();
        java.util.logging.Logger logger = lm.getLogger(name);
        if (logger != null) {
            return logger;
        }
        // Traverse up the hierarchy looking for an ancestor logger
        String current = name;
        while (true) {
            int lastDot = current.lastIndexOf('.');
            if (lastDot == -1) {
                break;
            }
            String parent = current.substring(0, lastDot);
            logger = lm.getLogger(parent);
            if (logger != null) {
                return logger;
            }
            current = parent;
        }
        // If no logger in the hierarchy was found, return null
        return null;
    } catch (Exception e) {
        // In case of unexpected issues, gracefully return null
        return null;
    }
}

