private void pop(final String descriptor) {
    int i = 0;
    int len = descriptor.length();
    if (len == 0) {
        return;
    }
    if (descriptor.charAt(0) == '(') {
        // method descriptor: pop argument types
        i = 1;
        while (i < len && descriptor.charAt(i) != ')') {
            // array dimensions
            while (i < len && descriptor.charAt(i) == '[') {
                i++;
            }
            // object type
            if (i < len && descriptor.charAt(i) == 'L') {
                i = descriptor.indexOf(';', i);
            }
            // pop a type from the stack
            outputFrameStack.pop();
            i++;
        }
        // skip ')' and the return type (do not pop it)
    } else {
        // field descriptor: pop a single type
        while (i < len && descriptor.charAt(i) == '[') {
            i++;
        }
        if (i < len && descriptor.charAt(i) == 'L') {
            i = descriptor.indexOf(';', i);
        }
        outputFrameStack.pop();
    }
}

private void pop(final String descriptor){
    int i = 0;
    int count = 0;
    boolean methodDesc = descriptor != null && descriptor.startsWith("(");
    if (methodDesc) {
        i = 1; // skip '('
    }
    while (i < descriptor.length()) {
        if (methodDesc && descriptor.charAt(i) == ')') {
            break;
        }
        char c = descriptor.charAt(i);
        switch (c) {
            case 'L':
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' in object type");
                }
                i = semicolon;
                count++;
                break;
            case 'J':
            case 'D':
                count += 2;
                break;
            case '[':
                // skip array brackets and continue processing the element type
                i++;
                continue;
            default:
                // primitives other than J and D occupy one slot
                count++;
        }
        i++;
    }
    pos -= count;
}

private void pop(final String descriptor){
    final int len = descriptor.length();
    int i = 0;
