private void pop(final String descriptor) {
    int count = 0;
    int i = 0;
    final int length = descriptor.length();

    // Helper to skip one type descriptor starting at index i
    // Returns new index after the type
    java.util.function.IntUnaryOperator skipOne = (idx) -> {
        int pos = idx;
        while (pos < length) {
            char c = descriptor.charAt(pos);
            if (c == 'L') { // reference type
                pos++;
                while (pos < length && descriptor.charAt(pos) != ';') {
                    pos++;
                }
                if (pos < length) pos++; // skip ';'
                break;
            } else if (c == '[') { // array, consume all '['
                pos++;
                continue;
            } else { // primitive type
                pos++;
                break;
            }
        }
        return pos;
    };

    if (descriptor.startsWith("(")) {
        i = 1; // skip '('
        while (i < length && descriptor.charAt(i) != ')') {
            i = skipOne.applyAsInt(i);
            count++;
        }
        // skip ')'
        if (i < length && descriptor.charAt(i) == ')') {
            i++;
        }
    } else {
        // single type descriptor
        count = 1;
    }

    // Ensure there are enough slots to pop
    if (pos < count) {
        throw new IllegalStateException("Attempted to pop "
                + count + " types but stack position is " + pos);
    }
    // Pop the types (here we simply decrement the position)
    pos -= count;
}

