public int compare(Double o1, Double o2) {
    // Handle nulls explicitly to avoid NullPointerException
    if (o1 == null && o2 == null) {
        return 0;
    }
    if (o1 == null) {
        return -1; // null is considered less than any non-null Double
    }
    if (o2 == null) {
        return 1; // any non-null Double is greater than null
    }

    double d1 = o1.doubleValue();
    double d2 = o2.doubleValue();

