public String format(final LoggingEvent event){
    if(event == null){
        throw new IllegalArgumentException("LoggingEvent must not be null");
    }
    try{
        java.lang.StringBuilder sb = new java.lang.StringBuilder();

        // Timestamp
        try{
            long ts = event.getTimeStamp();
            java.util.Date date = new java.util.Date(ts);
            sb.append(java.lang.String.format("[%%tF %%tT]", date));
        }catch(Exception e){
            sb.append("[UNKNOWN_TIMESTAMP]");
        }

        // Level
        try{
            sb.append(" [");
            sb.append(event.getLevel());
            sb.append("]");
        }catch(Exception e){
            sb.append(" [UNKNOWN_LEVEL]");
        }

        // Thread name
        try{
            sb.append(" [");
            sb.append(event.getThreadName());
            sb.append("]");
        }catch(Exception e){
            sb.append(" [UNKNOWN_THREAD]");
        }

        // Logger name
        try{
            sb.append(" [");
            sb.append(event.getLoggerName());
            sb.append("]");
        }catch(Exception e){
            sb.append(" [UNKNOWN_LOGGER]");
        }

        // Message
        try{
            sb.append(" : ");
            Object msg = event.getMessage();
            sb.append(msg != null ? msg : "null");
        }catch(Exception e){
            sb.append(" : <message_error>");
        }

        // Throwables (if any)
        try{
            if(event.getThrowableInformation() != null){
                java.lang.Throwable t = event.getThrowableInformation().getThrowable();
                if(t != null){
                    sb.append(" | Throwable: ");
                    sb.append(t.getClass().getName());
                    sb.append(": ");
                    sb.append(t.getMessage());
                }
            }
        }catch(Exception e){
            // ignore
        }

        sb.append(System.lineSeparator());
        return sb.toString();
    }catch(Exception e){
        return "Error formatting LoggingEvent: " + e.getMessage();
    }
}

