public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    if (desiredCapacity <= 3) {
        return 3;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (candidate > 0 && candidate <= Integer.MAX_VALUE) {
        boolean isPrime = true;
        int sqrt = (int) Math.sqrt(candidate);
        if (candidate < 2) {
            isPrime = false;
        } else if (candidate % 2 == 0 && candidate != 2) {
            isPrime = false;
        } else {
            for (int i = 3; i <= sqrt; i += 2) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2; // only check odd numbers
    }
    return Integer.MAX_VALUE; // fallback if no prime found within int range
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate++;
        // Avoid infinite loop in pathological cases by capping at Integer.MAX_VALUE
        if (candidate == Integer.MAX_VALUE) {
            throw new IllegalArgumentException("No prime found within integer range for desiredCapacity: " + desiredCapacity);
        }
    }
}

private static boolean isPrime(int n) {
    if (n <= 3) {
        return n > 1;
    }
    if (n % 2 == 0 || n % 3 == 0) {
        return false;
    }
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 5; i <= sqrtN; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // Make the candidate odd (unless it is 2, handled above)
    if ((candidate & 1) == 0) {
        candidate++;
    }
    while (candidate > 0) { // continue until overflow wraps to negative
        if (isPrime(candidate)) {
            return candidate;
        }
        // Avoid integer overflow in the loop increment
        if (candidate > Integer.MAX_VALUE - 2) {
            throw new IllegalArgumentException("Cannot find a suitable prime within the int range");
        }
        candidate += 2; // skip even numbers
    }
    throw new IllegalArgumentException("No suitable prime found");
}

private static boolean isPrime(int n){
    if (n < 2) {
        return false;
    }
    if (n == 2 || n == 3) {
        return true;
    }
    if ((n & 1) == 0 || n % 3 == 0) {
        return false;
    }
    int i = 5;
    int w = 2;
    while ((long)i * i <= n) {
        if (n % i == 0) {
            return false;
        }
        i += w;
        w = 6 - w;
    }
    return true;
}

public static int nextPrime(int desiredCapacity){
    // Handle small capacities explicitly
    if (desiredCapacity <= 2) return 2;
    // Start at desiredCapacity or the next odd number >= desiredCapacity
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    // If desired capacity is 1, set candidate to 3
    if (candidate < 3) candidate = 3;
    // Optional: restrict growth to within 11% if desiredCapacity >= 1000
    long maxCandidate = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        maxCandidate = desiredCapacity * 111L / 100; // 11% increase
    }
    while (true) {
        // Check for primality
        boolean isPrime = true;
        int sqrt = (int)Math.sqrt(candidate);
        for (int i = 3; i <= sqrt; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            // Ensure within the allowed range if limit is set
            if (candidate <= maxCandidate || desiredCapacity < 1000) {
                return candidate;
            }
        }
        // Move to the next odd number
        candidate += 2;
        // In the unlikely event we've overflowed, return Integer.MAX_VALUE prime approximation
        if (candidate < 0) {
            return Integer.MAX_VALUE;
        }
    }
}

public static int nextPrime(int desiredCapacity){
    // Handle edge cases
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // Ensure candidate is odd (all primes > 2 are odd)
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (true) {
        // Quick check for small numbers
        if (candidate <= 5) {
            if (candidate > 1) {
                return candidate;
            }
        } else {
            // Avoid dividing by zero and handle overflow
            if (candidate % 2 == 0 || candidate % 3 == 0) {
                // Not prime
            } else {
                boolean isPrime = true;
                int i = 5;
                // Use i*i <= candidate ; i increments by 6
                while ((long)i * i <= candidate) {
                    if (candidate % i == 0 || candidate % (i + 2) == 0) {
                        isPrime = false;
                        break;
                    }
                    i += 6;
                }
                if (isPrime) {
                    return candidate;
                }
            }
        }
        // Move to next odd candidate
        candidate += 2;
        // Prevent overflow
        if (candidate < 0) {
            // Integer overflow, return max value
            return Integer.MAX_VALUE;
        }
    }
}

