public void init(){
    // Determine distribution path
    String distPath = System.getProperty("dist.path");
    if (distPath == null || distPath.isEmpty()) {
        distPath = "dist";
    }

    java.io.File distDir = new java.io.File(distPath);
    try {
        if (distDir.exists()) {
            if (!distDir.isDirectory()) {
                throw new IllegalStateException("Dist path exists but is not a directory: " + distDir.getAbsolutePath());
            }
        } else {
            if (!distDir.mkdirs()) {
                throw new IllegalStateException("Unable to create distribution directory: " + distDir.getAbsolutePath());
            }
        }
    } catch (SecurityException se) {
        throw new IllegalStateException("Insufficient permissions to access distribution directory: " + distDir.getAbsolutePath(), se);
    } catch (RuntimeException re) {
        throw new IllegalStateException("Failed to initialize config: " + re.getMessage(), re);
    }
}

