@Override public String readString() throws IOException {
    // Read a 4-byte big-endian length prefix
    int length = 0;
    for (int i = 0; i < 4; i++) {
        int b = in.read();
        if (b == -1) {
            throw new EOFException("Unexpected end of stream while reading string length");
        }
        length = (length << 8) | (b & 0xFF);
    }
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }
    // Read the string bytes
    byte[] buffer = new byte[length];
    int offset = 0;
    while (offset < length) {
        int readCount = in.read(buffer, offset, length - offset);
        if (readCount == -1) {
            throw new EOFException("Unexpected end of stream while reading string data");
        }
        offset += readCount;
    }
    // Convert to String using UTF-8 encoding
    return new String(buffer, "UTF-8");
}

@Override public String readString() throws IOException {
    DataInputStream dis = new DataInputStream(this);
    int len = dis.readInt();
    if (len < 0) {
        throw new IOException("Negative string length: " + len);
    }
    byte[] bytes = new byte[len];
    dis.readFully(bytes);
    return new String(bytes, StandardCharsets.UTF_8);
}

