    if (set1.size() <= set2.size()) {
        for (V element : set1) {
            if (set2.contains(element)) {
                result.add(element);
            }
        }
    } else {
        for (V element : set2) {
            if (set1.contains(element)) {
                result.add(element);
            }
        }
    }
    return result;
}

