        java.util.Queue<Category> queue = new java.util.LinkedList<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            Category current = queue.poll();
            java.util.List<Category> children = current.getChildren();
            if (children != null) {
                java.util.Iterator<Category> it = children.iterator();
                while (it.hasNext()) {
                    Category child = it.next();
                    if (!child.isActive()) {
                        it.remove();
                        removedCount++;
                    } else {
                        queue.add(child);
                    }
                }
            }
        }
    } catch (Exception e) {
        // If logging is unavailable, wrap the exception in a RuntimeException
        throw new RuntimeException("Failed to remove unused nodes", e);
    }
    return removedCount;
}

protected int removeUnusedNodes(){
