    if (root == null) return 0;
    java.util.Deque<Category> stack = new java.util.ArrayDeque<Category>();
    stack.push(root);
    while (!stack.isEmpty()){
        Category node = stack.pop();
        try{
            java.util.List<Category> children = new java.util.ArrayList<Category>(node.getChildren());
            for (Category child : children){
                if (!child.isActive()){
                    node.removeChild(child);
                    removed++;
                } else {
                    stack.push(child);
                }
            }
        }catch(Exception e){
            // If removal fails, log and continue
            java.util.logging.Logger.getLogger(this.getClass().getName()).warning("Failed to process node: "+node+"; "+e.getMessage());
        }
    }
    return removed;
}

