    try{
        // Assume the tree root is stored in a field named 'root'
        // and each node has methods: boolean isActive(), List<Category> getChildren()
        if (root == null) return 0;
        // Use a stack to traverse the tree without recursion
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()){
            Category current = stack.pop();
            if (current == null) continue;
            java.util.List<Category> children = current.getChildren();
            if (children == null) continue;
            java.util.Iterator<Category> it = children.iterator();
            while (it.hasNext()){
                Category child = it.next();
                if (!child.isActive()){
                    // Remove inactive child
                    it.remove();
                    removedCount++;
                } else {
                    // Continue traversal
                    stack.push(child);
                }
            }
        }
    } catch (Exception e){
        // Log exception (assuming a LOG static field exists)
        if (LOG != null) {
            LOG.warn("Error while removing unused nodes: " + e.getMessage(), e);
        } else {
            e.printStackTrace();
        }
    }
