protected int removeUnusedNodes(){
    if (root == null) return 0;
    java.util.Stack<Category> stack = new java.util.Stack<>();
    java.util.Set<Category> seen = new java.util.HashSet<>();
    java.util.Map<Category, Category> parentMap = new java.util.HashMap<>();
    stack.push(root);
    parentMap.put(root, null);
    int removed = 0;
    while (!stack.isEmpty()){
        Category node = stack.pop();
        if (node == null) continue;
        if (seen.contains(node)){
            if (!node.isActive()){
                Category parent = parentMap.get(node);
                if (parent != null){
                    parent.getChildren().remove(node);
                    removed++;
                } else {
                    root = null;
                    removed++;
                }
            }
        } else {
            seen.add(node);
            stack.push(node);
            java.util.List<Category> children = node.getChildren();
            if (children != null){
                for (Category child : children){
                    stack.push(child);
                    parentMap.put(child, node);
                }
            }
        }
    }
    return removed;
}

protected int removeUnusedNodes(){
    int removedCount = 0;
    try{
        // Assume a root node field named 'root' of type Category exists.
        if(root == null){
            return removedCount;
        }
        // If the root itself is inactive, reset the tree.
        if(!root.isActive()){
            root = null;
            return 1;
        }
        // Use a stack for iterative depth-first traversal.
        java.util.Stack<Category> stack = new java.util.Stack<>();
        stack.push(root);
        while(!stack.isEmpty()){
            Category current = stack.pop();
            java.util.List<Category> children = current.getChildren();
            if(children == null){
                continue;
            }
            java.util.Iterator<Category> it = children.iterator();
            while(it.hasNext()){
                Category child = it.next();
                if(!child.isActive()){
                    // Remove inactive child.
                    it.remove();
                    removedCount++;
                }else{
                    // Continue traversal into active child.
                    stack.push(child);
                }
            }
        }
    }catch(Exception e){
        // Log or rethrow as needed; here we print stack trace.
        e.printStackTrace();
    }
    return removedCount;
}

