public int compare(Object aObj1, Object aObj2) {
    // Return 0 if both references are identical or both are null
    if (aObj1 == aObj2) {
        return 0;
    }
    // Treat null as lesser than non‑null
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }
    // Both objects must be of the same runtime type and implement Comparable
    if (aObj1.getClass() != aObj2.getClass() || !(aObj1 instanceof Comparable)) {
        throw new IllegalArgumentException(
            "Cannot compare objects of different types or types that do not implement Comparable");
    }
    @SuppressWarnings("unchecked")
    Comparable<Object> comp = (Comparable<Object>) aObj1;
    try {
        return comp.compareTo(aObj2);
    } catch (ClassCastException e) {
        throw new IllegalArgumentException(
            "Objects are not mutually comparable: " + e.getMessage(), e);
    }
}

public int compare(Object aObj1, Object aObj2) {
    // Handle nulls: null is considered less than any non-null value
    if (aObj1 == aObj2) {
        return 0;
    }
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }
    // Ensure the arguments are byte arrays; otherwise throw
    if (!(aObj1 instanceof byte[]) || !(aObj2 instanceof byte[])) {
        throw new IllegalArgumentException("Arguments must be byte arrays");
    }
    byte[] a1 = (byte[]) aObj1;
    byte[] a2 = (byte[]) aObj2;
    int len1 = a1.length;
    int len2 = a2.length;
    int minLen = Math.min(len1, len2);
    // Compare lexicographically
    for (int i = 0; i < minLen; i++) {
        int cmp = Byte.compare(a1[i], a2[i]);
        if (cmp != 0) {
            return cmp;
        }
    }
    // If all elements are equal up to the shorter length, prefer the shorter array
    return Integer.compare(len1, len2);
}

