protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    try {
        if (tour == null || graph == null || tour.isEmpty()) {
            return null;
        }
        // Use a copy so we can remove edges as we traverse
        Set<E> remaining = new LinkedHashSet<>(tour);
        // Start with an arbitrary edge
        Iterator<E> it = remaining.iterator();
        E first = it.next();
        it.remove();
        // Determine order of vertices along the tour
        List<V> vertexList = new ArrayList<>();
        List<E> edgeList = new ArrayList<>();
        V curr = graph.getEdgeSource(first);
        V next = graph.getEdgeTarget(first);
        if (next.equals(curr)) { // handle potential self-loop
            next = graph.getEdgeSource(first);
        }
        vertexList.add(curr);
        vertexList.add(next);
        edgeList.add(first);
        curr = next;
        // Walk the rest of the edges
        while (!remaining.isEmpty()) {
            E chosen = null;
            for (E e : remaining) {
                V src = graph.getEdgeSource(e);
                V tgt = graph.getEdgeTarget(e);
                if (src.equals(curr) || tgt.equals(curr)) {
                    chosen = e;
                    break;
                }
            }
            if (chosen == null) {
                // No connecting edge found – invalid tour
                break;
            }
            remaining.remove(chosen);
            edgeList.add(chosen);
            V src = graph.getEdgeSource(chosen);
            V tgt = graph.getEdgeTarget(chosen);
            V newVertex = src.equals(curr) ? tgt : src;
            vertexList.add(newVertex);
            curr = newVertex;
        }
        // Ensure cycle closure
        if (!vertexList.get(0).equals(vertexList.get(vertexList.size() - 1))
                && !vertexList.isEmpty()) {
            vertexList.add(vertexList.get(0));
        }
        // Construct and return a GraphPath (assumes such a constructor exists)
        return new GraphPath<V, E>(vertexList, edgeList);
    } catch (Exception e) {
        return null;
    }
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()) {
        return new DefaultGraphPath<>(graph);
    }
    // map from vertex to incident edges for quick lookup
    Map<V, List<E>> vertexToEdges = new HashMap<>();
    for (E e : tour) {
        V v1 = e.inVertex();
        V v2 = e.outVertex();
        vertexToEdges.computeIfAbsent(v1, k -> new ArrayList<>()).add(e);
        vertexToEdges.computeIfAbsent(v2, k -> new ArrayList<>()).add(e);
    }

    // pick arbitrary start edge
    Iterator<E> it = tour.iterator();
    E startEdge = it.next();
    Set<E> remaining = new HashSet<>(tour);
    remaining.remove(startEdge);

    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    // start from the "in" vertex of the first edge
    V current = startEdge.inVertex();
    vertices.add(current);
    V next = startEdge.outVertex();
    vertices.add(next);
    edges.add(startEdge);
    current = next;

    // walk through remaining edges
    while (!remaining.isEmpty()) {
        List<E> candidates = vertexToEdges.getOrDefault(current, Collections.emptyList());
        E chosen = null;
        for (E e : candidates) {
            if (remaining.contains(e)) {
                chosen = e;
                break;
            }
        }
        if (chosen == null) {
            throw new IllegalArgumentException("Edge set does not form a single connected path");
        }
        remaining.remove(chosen);
        edges.add(chosen);
        V other = chosen.inVertex().equals(current) ? chosen.outVertex() : chosen.inVertex();
        vertices.add(other);
        current = other;
    }

    return new DefaultGraphPath<>(graph, vertices, edges);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()){
        return null;
    }
    // Build adjacency map from vertices to incident edges
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour){
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
    }
    // Pick an arbitrary start vertex
    E firstEdge = tour.iterator().next();
    V start = graph.getEdgeSource(firstEdge);
    V current = start;
    List<E> edgeList = new ArrayList<>(tour.size());
    Set<E> remaining = new HashSet<>(tour);
    // Walk along the tour
    while (!remaining.isEmpty()){
        List<E> edgesAtCurr = adjacency.get(current);
        if (edgesAtCurr == null){
            return null; // invalid tour
        }
        E next = null;
        for (E e : edgesAtCurr){
            if (remaining.contains(e)){
                next = e;
                break;
            }
        }
        if (next == null){
            return null; // disconnected or non‑circular
        }
        edgeList.add(next);
        remaining.remove(next);
        // Move to the other vertex of the edge
        V u = graph.getEdgeSource(next);
        V v = graph.getEdgeTarget(next);
        current = current.equals(u) ? v : u;
    }
    // Compute total weight of the tour
    double weight = 0.0;
    for (E e : edgeList){
        weight += graph.getEdgeWeight(e);
    }
    // Create a concrete GraphPath (GraphWalk implements GraphPath)
    return new org.jgrapht.graph.GraphWalk<>(graph, start, current, edgeList, weight);
}

