    // Choose a start vertex
    V start = null;
    if (graph.getType().isDirected()){
        for (V v : incident.keySet()){
            long out = tour.stream().filter(e -> graph.getEdgeSource(e).equals(v)).count();
            if (out == 1){
                start = v;
                break;
            }
        }
        if (start == null && !incident.isEmpty()){
            start = incident.keySet().iterator().next();
        }
    } else {
        for (V v : incident.keySet()){
            if (incident.get(v).size() == 1){
                start = v;
                break;
            }
        }
        if (start == null && !incident.isEmpty()){
            start = incident.keySet().iterator().next();
        }
    }
    if (start == null){
        return null;
    }

    // Build ordered path
    List<V> vertexList = new ArrayList<>();
    vertexList.add(start);
    List<E> edgeList = new ArrayList<>();
    Set<E> used = new HashSet<>();
    V current = start;

    while (edgeList.size() < edgeCount){
        E chosen = null;
        for (E e : incident.getOrDefault(current, List.of())){
            if (used.contains(e)){
                continue;
            }
            if (graph.getType().isDirected()){
                if (!graph.getEdgeSource(e).equals(current)){
                    continue;
                }
            }
            chosen = e;
            break;
        }
        if (chosen == null){
            break;
        }
        used.add(chosen);
        edgeList.add(chosen);
        V next = graph.getEdgeSource(chosen).equals(current)
                 ? graph.getEdgeTarget(chosen)
                 : graph.getEdgeSource(chosen);
        vertexList.add(next);
        current = next;
    }

    // If we did not use all edges, we cannot form a single path
    if (edgeList.size() != edgeCount){
        return null;
    }

    V end = vertexList.get(vertexList.size() - 1);
    double totalWeight = 0.0;
    for (E e : edgeList){
        totalWeight += graph.getEdgeWeight(e);
    }
    return new GraphWalk<>(graph, start, end, vertexList, edgeList, totalWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) return null;
    if (tour.isEmpty()) return null;
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour){
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }
    Iterator<E> it = tour.iterator();
    if (!it.hasNext()) return null;
    E startEdge = it.next();
    V startVertex = graph.getEdgeSource(startEdge);
    V current = startVertex;
    Set<E> remaining = new HashSet<>(tour);
    List<E> orderedEdges = new ArrayList<>();
    while (!remaining.isEmpty()){
        E nextEdge = null;
        for (E e : remaining){
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current) || tgt.equals(current)){
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) return null;
        orderedEdges.add(nextEdge);
        remaining.remove(nextEdge);
        V src = graph.getEdgeSource(nextEdge);
        V tgt = graph.getEdgeTarget(nextEdge);
        current = src.equals(current) ? tgt : src;
    }
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);
    V prev = startVertex;
    for (E e : orderedEdges){
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        V next = src.equals(prev) ? tgt : src;
        vertexList.add(next);
        prev = next;
    }
    // Use JGraphT's GraphPathImpl to construct the path
    return new GraphPathImpl<>(graph, vertexList, orderedEdges);
}

