int addConstantNameAndType(final String name, final String descriptor){
    // Locate or add the UTF‑8 constants for the name and descriptor.
    int nameIdx   = findUtf8(name);
    if (nameIdx == NOT_FOUND) nameIdx = addUtf8(name);
    int descIdx   = findUtf8(descriptor);
    if (descIdx == NOT_FOUND) descIdx = addUtf8(descriptor);

    // Check whether a NAME_AND_TYPE constant with the desired pair already exists.
    int existing = findNameAndType(nameIdx, descIdx);
    if (existing != NOT_FOUND) {
        return existing;
    }

    // Allocate a new slot for the constant pool entry.
    int idx = maxPoolSize;
    // Ensure the backing arrays can hold the new entry (implementation dependent).
    // This example assumes the arrays are large enough or will be resized elsewhere.

    // Store the entry in the constant pool.
    types[idx] = NAME_TYPE;      // constant pool tag for NameAndType
    offsets[idx]     = nameIdx;  // reference to the UTF‑8 name
    offsets[idx + 1] = descIdx; // reference to the UTF‑8 descriptor

    // Update the pool size to account for the two extra indices needed.
    maxPoolSize = idx + 2;
    return idx;
}

int addConstantNameAndType(final String name,final String descriptor){
    // Check if the pair already exists
    int existing = findNameAndType(name, descriptor);
    if (existing != NOT_FOUND) {
        return existing;
    }

    // Make sure the name and descriptor strings exist in the constant pool
    int nameIndex = findUtf8(name);
    if (nameIndex == NOT_FOUND) {
        nameIndex = addUtf8(name);
    }
    int descIndex = findUtf8(descriptor);
    if (descIndex == NOT_FOUND) {
        descIndex = addUtf8(descriptor);
    }

    // Ensure there is room for the new entry
    if (maxPoolSize >= types.length) {
        int newSize = Math.max(types.length * 2, maxPoolSize + 1);
        types = Arrays.copyOf(types, newSize);
        nameAndTypeNameIndices = Arrays.copyOf(nameAndTypeNameIndices, newSize);
        nameAndTypeDescIndices = Arrays.copyOf(nameAndTypeDescIndices, newSize);
    }

    // Insert the new CONSTANT_NameAndType_info
    int newIndex = maxPoolSize;
    types[newIndex] = NAME_TYPE;
    nameAndTypeNameIndices[newIndex] = nameIndex;
    nameAndTypeDescIndices[newIndex] = descIndex;
    maxPoolSize++;

    return newIndex;
}

int addConstantNameAndType(final String name, final String descriptor){
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    // Check if a similar constant already exists
    int existing = findNameAndType(name, descriptor);
    if (existing != NOT_FOUND) {
        return existing + 1;                // constant pool indices are 1-based
    }
    // Ensure that the name and descriptor themselves are present
    int nameIdx = addConstantUtf8(name);
    int descIdx = addConstantUtf8(descriptor);
    // Add the new NameAndType constant
    int newIdx = addNameAndType(nameIdx, descIdx);
    return newIdx + 1;
}

int addConstantNameAndType(final String name,final String descriptor){
    // Ensure name and descriptor Utf8 constants exist
    int nameIdx = findUtf8(name);
    if(nameIdx == -1)
        nameIdx = addUtf8(name);
    int descIdx = findUtf8(descriptor);
    if(descIdx == -1)
        descIdx = addUtf8(descriptor);

    // Search existing constant pool for a matching NameAndType entry
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE) {
            // The NAME_TYPE entry is assumed to contain two u2 indices:
            // first the name index, then the descriptor index.
            // The offset of the data for entry i is given by offsets[i].
            int off = offsets[i];
            int existingNameIdx = ((byteCode[off] & 0xFF) << 8) | (byteCode[off + 1] & 0xFF);
            int existingDescIdx = ((byteCode[off + 2] & 0xFF) << 8) | (byteCode[off + 3] & 0xFF);
            if (existingNameIdx == nameIdx && existingDescIdx == descIdx) {
                return i;
            }
        }
    }

    // No existing entry found – create a new one
    int newIndex = ++maxPoolSize;
    // Ensure arrays are large enough (resize if required)
    try {
        types[newIndex] = NAME_TYPE;
        // The raw data for the NameAndType entry is two ushort values.
        // We write them directly into the byteCode array starting at the
        // current end of the constant pool.  We also record the offset.
        int offset = byteCode.length;
        // Resize byteCode to accommodate two more u2 values
        byteCode = java.util.Arrays.copyOf(byteCode, offset + 4);
        byteCode[offset] = (byte) (nameIdx >> 8);
        byteCode[offset + 1] = (byte) (nameIdx & 0xFF);
        byteCode[offset + 2] = (byte) (descIdx >> 8);
        byteCode[offset + 3] = (byte) (descIdx & 0xFF);
        // Store the offset of the data for this entry
        offsets[newIndex] = offset;
    } catch (Exception e) {
        // If any error occurs (unlikely in a real constant pool),
        // re-throw as unchecked to terminate compilation.
        throw new RuntimeException("Failed to add NameAndType constant", e);
    }

    return newIndex;
}

int addConstantNameAndType(final String name, final String descriptor){
    // Composite key for the NameAndType pair
    final String key = name + '\0' + descriptor;

    // Return existing index if this pair is already present
    if (nameAndTypeMap.containsKey(key)) {
        return nameAndTypeMap.get(key);
    }

    // Ensure UTF8 constants for name and descriptor exist
    int nameIdx;
    int descriptorIdx;
    try {
        // Use existing mapping if available; otherwise add the UTF8 constant
        if (utf8Map.containsKey(name)) {
            nameIdx = utf8Map.get(name);
        } else {
            nameIdx = addUtf8Constant(name);
            utf8Map.put(name, nameIdx);
        }

        if (utf8Map.containsKey(descriptor)) {
            descriptorIdx = utf8Map.get(descriptor);
        } else {
            descriptorIdx = addUtf8Constant(descriptor);
            utf8Map.put(descriptor, descriptorIdx);
        }
    } catch (Exception e) {
        // In case of any failure while adding UTF8 entries, propagate a runtime exception
        throw new RuntimeException("Failed to add UTF8 constants for NameAndType", e);
    }

    // Allocate next available index in the constant pool
    final int nextIndex = ++constantPoolNextIndex;
    try {
        // Store the NameAndType constant at the allocated index
        types[nextIndex] = (byte)CONSTANT_NameAndType; // CONSTANT_NameAndType tag is 12
        nameIndices[nextIndex] = nameIdx;
        descriptorIndices[nextIndex] = descriptorIdx;

        // Persist the mapping from (name,descriptor) -> pool index
        nameAndTypeMap.put(key, nextIndex);
    } catch (ArrayIndexOutOfBoundsException ex) {
        // Resize structures if necessary
        expandConstantPool();
        // After expansion, retry storing the constant
        types[nextIndex] = (byte)CONSTANT_NameAndType;
        nameIndices[nextIndex] = nameIdx;
        descriptorIndices[nextIndex] = descriptorIdx;
        nameAndTypeMap.put(key, nextIndex);
    }

    return nextIndex;
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(input.length());
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            // Skip the escape character and add the escaped char
            sb.append(input.charAt(i + 1));
            i++; // advance past the escaped char
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

