        return;
    }
    // Guard against popping more elements than are on the stack
    if (elements > pos) {
        throw new IllegalStateException("Cannot pop " + elements + " elements from stack; only " + pos + " available.");
    }
    for (int i = 0; i < elements; i++) {
        // Clear reference to help GC and decrement position pointer
        stack[--pos] = null;
    }
}

