private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    try {
        // Adjust the previous node
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            // node was the first element
            first = node.next;
        }
        // Adjust the next node
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            // node was the last element
            last = node.prev;
        }
        // Clean up the removed node's links
        node.next = null;
        node.prev = null;
        // Update the size of the list
        if (size > 0) {
            size--;
