public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    // Find last path separator (both Unix and Windows)
    int lastSlash = path.lastIndexOf('/');
    int lastBackSlash = path.lastIndexOf('\\');
    int lastSep = Math.max(lastSlash, lastBackSlash);

    // Find last dot after the last separator
    int lastDot = path.lastIndexOf('.');
    if (lastDot == -1 || lastDot <= lastSep) {
        // No extension found
        return null;
    }

    // Avoid treating a leading dot in the file name as an extension
    if (lastDot <= lastSep + 1) {
        return null;
    }

    return path.substring(0, lastDot);
}

public static String stripFilenameExtension(String path){
    if (path == null) return null;
    int lastSeparator = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int lastDot = path.lastIndexOf('.');
    if (lastDot <= lastSeparator) {
        return null;
    }
    return path.substring(0, lastDot);
}

public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    // Find the last directory separator (supports both '/' and '\\')
    int sepIndex = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // Find the last dot
    int dotIndex = path.lastIndexOf('.');
    // No dot or dot is part of a directory name
    if (dotIndex == -1 || dotIndex <= sepIndex) {
        return path;
    }
    // Return path without the extension
    return path.substring(0, dotIndex);
}

