private String parseToken(final char[] terminators) {
    // If the terminators array is null or empty, consume all remaining characters.
    if (terminators == null || terminators.length == 0) {
        if (pos >= chars.length) {
            return "";
        }
        int remaining = chars.length - pos;
        String token = new String(chars, pos, remaining);
        pos = chars.length;
        return token;
    }

    // Mark the start of the token.
    int start = pos;

    // Advance the position until a terminator is found or the end of the stream is reached.
    while (pos < chars.length) {
        char current = chars[pos];
        boolean isTerminator = false;
        for (char t : terminators) {
            if (current == t) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            break;
        }
        pos++;
    }

    // Determine the length of the token.
    int length = pos - start;
    if (length <= 0) {
        return "";
    }

    // Return the token as a string.
    return new String(chars, start, length);
}

