private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        return;
    }
    // Start from the head of the source list
    ListNodeImpl<E> current = list.firstNode(); // obtain the first node of the source list
    while (current != null) {
        // Cache the next node before we change links
        ListNodeImpl<E> next = current.next(); // assume a next() accessor exists
        // Atomically remove from the source list
        list.removeListNode(current);
        // Add to this list
        this.addListNode(current);
        // Continue with the cached next node
        current = next;
    }
}

