        return;
    }
    Object targetBean = this.getBean();
    if (targetBean == null) {
        return;
    }
    try {
        java.beans.BeanInfo targetInfo = java.beans.Introspector.getBeanInfo(targetBean.getClass());
        java.beans.PropertyDescriptor[] targetPds = targetInfo.getPropertyDescriptors();
        for (Object keyObj : map.keySet()) {
            if (keyObj == null) {
                continue;
            }
            String property = keyObj.toString();
            boolean writable = false;
            for (java.beans.PropertyDescriptor pd : targetPds) {
                if (pd.getName().equals(property) && pd.getWriteMethod() != null) {
                    writable = true;
                    break;
                }
            }
            if (!writable) {
                continue;
            }
            try {
                Object value = map.get(property);
                this.put(property, value);
            } catch (Exception e) {
                // source property might be write‑only/not readable; skip
            }
        }
    } catch (Exception e) {
        // unable to introspect; nothing to copy
    }
}

