public void abbreviate(final int nameStart, final StringBuffer buf) {
    try {
        if (name == null) {
            return;
        }
        int len = name.length();
        if (nameStart < 0 || nameStart >= len) {
            return;
        }
        String sub = name.substring(nameStart).trim();
        if (sub.isEmpty()) {
            return;
        }
        String[] words = sub.split("\\s+");
        for (String word : words) {
            if (!word.isEmpty()) {
                buf.append(word.charAt(0)).append('.');
            }
        }
    } catch (IndexOutOfBoundsException e) {
        // ignore invalid start indices, nothing to abbreviate
    } catch (Exception e) {
        // swallow any unexpected exception
    }
}

public void abbreviate(final int nameStart,final StringBuffer buf){
    if (buf == null) return;
    String name = this.name; // assume a field named 'name' containing the full name
    if (name == null || name.isEmpty()) return;
    int len = name.length();
    if (nameStart < 0 || nameStart >= len) return;
    StringBuilder abbr = new StringBuilder();
    boolean nextWord = true;
    for (int i = nameStart; i < len; ++i) {
        char c = name.charAt(i);
        if (Character.isWhitespace(c)) {
            nextWord = true;
        } else if (nextWord) {
            abbr.append(Character.toUpperCase(c));
            nextWord = false;
        }
    }
    buf.append(abbr);
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (name == null || name.isEmpty()) {
        return;
    }
    int start = Math.max(0, nameStart);
    if (start >= name.length()) {
        return;
    }
    String remaining = name.substring(start);
    String[] parts = remaining.split("\\s+");
    for (int i = 0; i < parts.length; i++) {
        if (i > 0) {
            buf.append(' ');
        }
        if (parts[i].length() > 0) {
            if (i == parts.length - 1) {
                buf.append(parts[i]);
            } else {
                buf.append(parts[i].charAt(0)).append('.');
            }
        }
    }
}

