private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    List<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V vj = list.get(j);
            E edge = graph.getEdge(vi, vj);
            if (edge == null) {
                edge = graph.getEdge(vj, vi);
                if (edge == null) {
                    return false;
                }
            }
        }
    }
    return true;
}

