    }
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (K keyObj : keys) {
        Integer key = null;
        if (keyObj instanceof Integer) {
            key = (Integer) keyObj;
        } else {
            try {
                key = Integer.valueOf(keyObj.toString());
            } catch (NumberFormatException e) {
