            }
        }
        if (key == null) {
            lowerBounds.add(null);
            continue;
        }
        Integer maxLower = null;
        for (K otherObj : keys) {
            if (otherObj == keyObj) continue;
            Integer other = null;
            if (otherObj instanceof Integer) {
                other = (Integer) otherObj;
            } else {
                try {
                    other = Integer.valueOf(otherObj.toString());
                } catch (NumberFormatException e) {
                    continue;
                }
            }
            if (other != null && other < key) {
                if (maxLower == null || other > maxLower) {
                    maxLower = other;
                }
            }
        }
        lowerBounds.add(maxLower);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()) return result;
    try {
        // Convert keys to Integer list
        List<Integer> intKeys = new ArrayList<>();
        for (K key : keys) {
            if (key == null) continue;
            intKeys.add((Integer) key);
        }
        Collections.sort(intKeys);
        for (K key : keys) {
            if (key == null) {
                result.add(Integer.MIN_VALUE);
                continue;
            }
            int val = (Integer) key;
            int idx = Collections.binarySearch(intKeys, val);
            if (idx < 0) {
                idx = -idx - 1; // insertion point
            }
            int lower = Integer.MIN_VALUE;
            if (idx > 0) {
                lower = intKeys.get(idx - 1);
            } else if (idx < intKeys.size() && intKeys.get(idx) < val) {
                lower = intKeys.get(idx);
            }
            result.add(lower);
        }
    } catch (ClassCastException e) {
        // If keys are not Integer, return minima as default
        for (int i = 0; i < keys.size(); i++) {
            result.add(Integer.MIN_VALUE);
        }
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>(keys.size());
    List<K> sorted = new ArrayList<>(keys);
    Collections.sort((List)sorted);
    for (K key : keys) {
        int idx = Collections.binarySearch((List)sorted, key);
        if (idx < 0) {
            int insertionPoint = -idx - 1;
            bounds.add(insertionPoint - 1 >= 0 ? insertionPoint - 1 : -1);
        } else {
            bounds.add(idx);
        }
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    int n = keys.size();
    List<Integer> lowerBounds = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        if (keys.get(i) == null) {
            throw new IllegalArgumentException("key at index " + i + " is null");
        }
        K maxKey = null;
        int maxIndex = -1;
        for (int j = 0; j < n; j++) {
            if (j == i) {
                continue;
            }
            K candidate = keys.get(j);
            if (candidate == null) {
                throw new IllegalArgumentException("key at index " + j + " is null");
            }
            if (((Comparable<K>) candidate).compareTo(keys.get(i)) < 0) {
                if (maxKey == null || ((Comparable<K>) candidate).compareTo(maxKey) > 0) {
                    maxKey = candidate;
                    maxIndex = j;
                }
            }
        }
        lowerBounds.add(maxIndex);
    }
    return lowerBounds;
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int count = 0;
    if (descriptor.charAt(0) == '('){
        int end = descriptor.indexOf(')');
        if (end < 0){
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
        String args = descriptor.substring(1, end);
        for (int i = 0; i < args.length();){
            char c = args.charAt(i);
            i++;
            if (c == 'L'){
                while (i < args.length() && args.charAt(i) != ';'){
                    i++;
                }
                if (i < args.length()){
                    i++; // skip ';'
                }
            } else if (c == '['){
                while (i < args.length() && args.charAt(i) == '['){
                    i++;
                }
                if (i < args.length()){
                    if (args.charAt(i) == 'L'){
                        i++;
                        while (i < args.length() && args.charAt(i) != ';'){
                            i++;
                        }
                        if (i < args.length()){
                            i++;
                        }
                    } else {
                        i++; // primitive component
                    }
                }
            } else {
                // primitive type, nothing else needed
            }
            count++;
        }
    } else {
        // single type descriptor; pop one slot
        count = 1;
    }
    while (count-- > 0 && pos > 0){
        pos--; // assume 'pos' tracks top of the output frame stack
    }
}

private void pop(final String descriptor){
    int count = 0;
    int i = 0;
    try{
        if(i < descriptor.length() && descriptor.charAt(i) == '('){
            // method descriptor – pop argument types only
            i++; // skip '('
            while(i < descriptor.length() && descriptor.charAt(i) != ')'){
                // skip array dimensions
                while(i < descriptor.length() && descriptor.charAt(i) == '['){
                    i++;
                }
                // skip object type
                if(i < descriptor.length() && descriptor.charAt(i) == 'L'){
                    while(i < descriptor.length() && descriptor.charAt(i) != ';'){
                        i++;
                    }
                    i++; // skip ';'
                }else{
                    // primitive type – single character
                    i++;
                }
                count++;
            }
        }else{
            // not a method descriptor – just a single type
            count = 1;
        }
    }catch(StringIndexOutOfBoundsException e){
        // bad descriptor – default to popping one type
        count = 1;
    }
    // pop the counted number of types from the output stack
    pos -= count;
    if(pos < 0) pos = 0;
}

private void pop(final String descriptor){
    if (descriptor == null) throw new NullPointerException("descriptor");
    int i = 0;
    int length = descriptor.length();
    if (length == 0) return;

    // Handle void descriptor
    if ("V".equals(descriptor)) return;

    // If descriptor starts with '(' it is a method descriptor
    if (descriptor.charAt(0) == '(') {
        i = 1;
        while (i < length && descriptor.charAt(i) != ')') {
            // pop one type
            if (pos <= 0) break; // stack underflow safeguard
            stack[--pos] = null;
            char c = descriptor.charAt(i);
            if (c == 'L') {
                // reference type ends with ';'
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon < 0) throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
                i = semicolon + 1;
            } else if (c == '[') {
                // array type, could be multi-dimensional
                i++;
                while (i < length && descriptor.charAt(i) == '[') i++;
                // component type
                if (i < length && descriptor.charAt(i) == 'L') {
                    int semicolon = descriptor.indexOf(';', i);
                    if (semicolon < 0) throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
                    i = semicolon + 1;
                } else {
                    // primitive component, single char
                    i++;
                }
            } else {
                // primitive type, single char
                i++;
            }
        }
    } else {
        // descriptor is a single type
        if (pos <= 0) return; // nothing to pop
        stack[--pos] = null;
    }
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int slots = 0;
    int i = 0;
    // Method descriptor: pop argument types only
    if (descriptor.charAt(0) == '(') {
        i = 1;
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == '[') {
                // skip all array brackets
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i >= descriptor.length()) break;
                c = descriptor.charAt(i);
            }
            if (c == 'L') {
                // object type: consume until ';'
                i = descriptor.indexOf(';', i);
                if (i == -1) break; // malformed descriptor
                i++; // skip ';'
                slots += 1;
            } else {
                // primitive type
                if (c == 'J' || c == 'D') {
                    slots += 2;
                } else {
                    // all others take 1 slot
                    slots += 1;
                }
                i++; // move past primitive
            }
        }
        // Ignore return type after ')'
    } else {
        // Single type descriptor
        char c = descriptor.charAt(0);
        if (c == '[') {
            // Skip array brackets
            while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= descriptor.length()) return;
            c = descriptor.charAt(i);
        }
        if (c == 'L') {
            slots = 1;
        } else if (c == 'J' || c == 'D') {
            slots = 2;
        } else if (c == 'V') {
            slots = 0; // void: nothing to pop
        } else {
            slots = 1;
        }
    }
    // Adjust stack pointer, ensuring it doesn't go negative
    pos -= slots;
    if (pos < 0) {
        pos = 0;
    }
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int count = 0;
    // Determine if descriptor is a method descriptor
    if (descriptor.charAt(0) == '('){
        int close = descriptor.indexOf(')');
        if (close < 0){
            return; // malformed descriptor
        }
        String args = descriptor.substring(1, close);
        int i = 0;
        while (i < args.length()){
            // Skip all array dimension brackets
            while (i < args.length() && args.charAt(i) == '['){
                i++;
            }
            // Count one abstract type
            count++;
            if (i >= args.length()){
                return; // malformed
            }
            char c = args.charAt(i);
            if (c == 'L'){
                // Object type: skip until ';'
                int semicolon = args.indexOf(';', i);
                if (semicolon < 0){
                    return; // malformed
                }
                i = semicolon + 1;
            } else {
                // Primitive type: single char
                i++;
            }
        }
    } else {
        // Not a method descriptor; a single type to pop
        count = 1;
    }
    // Pop the determined number of abstract types from the output frame stack
    for (int j = 0; j < count; j++){
        pos--;
    }
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys cannot be null");
    }
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            bounds.add(null);
        } else {
            int value;
            if (key instanceof Integer) {
                value = (Integer) key;
            } else if (key instanceof Number) {
                value = ((Number) key).intValue();
            } else {
                value = key.hashCode();
            }
            bounds.add(value);
        }
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys) {
    if (keys == null) {
        throw new IllegalArgumentException("keys cannot be null");
    }
    List<Integer> upperBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        K current = keys.get(i);
        if (current == null) {
            upperBounds.add(-1);
            continue;
        }
        K minCandidate = null;
        int minIndex = -1;
        for (int j = 0; j < keys.size(); j++) {
            K candidate = keys.get(j);
            if (candidate == null) {
                continue;
            }
            try {
                @SuppressWarnings("unchecked")
                Comparable<K> cmpCandidate = (Comparable<K>) candidate;
                if (cmpCandidate.compareTo(current) >= 0) {
                    if (minCandidate == null || cmpCandidate.compareTo(minCandidate) < 0) {
                        minCandidate = candidate;
                        minIndex = j;
                    }
                }
            } catch (ClassCastException e) {
                // Candidate does not implement Comparable, skip it
            }
        }
        upperBounds.add(minIndex);
    }
    return upperBounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys cannot be null");
    }
    List<Integer> upperBounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            upperBounds.add(0);
        } else {
            int bound = key.hashCode();
            // Ensure non‑negative and avoid Integer.MIN_VALUE overflow
            if (bound == Integer.MIN_VALUE) {
                bound = 0;
            } else {
                bound = Math.abs(bound);
            }
            upperBounds.add(bound);
        }
    }
    return upperBounds;
}

