public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non‑null");
    }
    try {
        java.nio.file.Path base = java.nio.file.Paths.get(path);
        java.nio.file.Path result = base.resolve(relativePath).normalize();
        return result.toString();
    } catch (Exception e) {
        // Fallback pathological handling
        if (relativePath.isEmpty() || relativePath.equals(".")) {
            return path;
        }
        // Basic manual resolution for "../" components
        java.util.List<String> baseParts = new java.util.ArrayList<>(java.util.Arrays.asList(path.split("/")));
        java.util.List<String> relParts = java.util.Arrays.asList(relativePath.split("/"));
        java.util.List<String> stack = new java.util.ArrayList<>();
        for (String part : baseParts) {
            if (!part.isEmpty()) stack.add(part);
        }
        for (String part : relParts) {
            if (part.equals("..")) {
                if (!stack.isEmpty()) stack.remove(stack.size() - 1);
            } else if (!part.equals(".") && !part.isEmpty()) {
                stack.add(part);
            }
        }
        StringBuilder sb = new StringBuilder();
        if (path.startsWith("/")) sb.append("/");
        for (int i = 0; i < stack.size(); i++) {
            if (i > 0) sb.append("/");
            sb.append(stack.get(i));
        }
        return sb.toString();
    }
}

public static String applyRelativePath(String path,String relativePath){
    if(path == null || relativePath == null){
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    boolean absolute = path.startsWith("/");
    String[] baseTokens = path.split("/");
    String[] relTokens = relativePath.split("/");
    java.util.List<String> stack = new java.util.ArrayList<>();
    for(String token : baseTokens){
        if(token.isEmpty()){
            continue;
        }
        stack.add(token);
    }
    for(String token : relTokens){
        if(token.isEmpty() || token.equals(".")){
            continue;
        } else if(token.equals("..")){
            if(!stack.isEmpty()){
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(token);
        }
    }
    StringBuilder sb = new StringBuilder();
    if(absolute){
        sb.append("/");
    }
    for(int i = 0; i < stack.size(); i++){
        sb.append(stack.get(i));
        if(i < stack.size() - 1){
            sb.append("/");
        }
    }
    // if the path is absolute but stack is empty, return "/"
    if(absolute && stack.isEmpty()){
        return "/";
    }
    return sb.toString();
}

public static String applyRelativePath(String path,String relativePath){
    if (path==null || relativePath==null){
        return null;
    }
    try{
        String normalizedPath = path.replace("\\","/").trim();
        String rel = relativePath.replace("\\","/").trim();
        if (rel.startsWith("/")){
            rel = rel.substring(1);
        }
        java.nio.file.Path base = java.nio.file.Paths.get(normalizedPath);
        java.nio.file.Path resolved = base.resolve(rel);
        java.nio.file.Path normalized = resolved.normalize();
        return normalized.toString();
    }catch(Exception e){
