    }
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath cannot be null");
    }
    try {
        java.nio.file.Path base = java.nio.file.Paths.get(path);
        java.nio.file.Path rel = java.nio.file.Paths.get(relativePath);
        java.nio.file.Path resolved = base.resolve(rel).normalize();
        String result = resolved.toString();
        // Use forward slashes for consistency across platforms
        if (System.getProperty("os.name").toLowerCase().contains("win")) {
            result = result.replace('\\', '/');
        }
        return result;
    } catch (IllegalArgumentException e) {
        throw new IllegalArgumentException("Invalid path components", e);
    }
}

public static String applyRelativePath(String path,String relativePath){
    if(path==null || relativePath==null) return null;
    // Preserve leading slash if present
    boolean leadingSlash = path.startsWith("/");
    java.util.List<String> stack = new java.util.ArrayList<>();
    // Process base path
    for(String part: path.split("/")){
        if(part.isEmpty() || part.equals(".")) continue;
        if(part.equals("..")){
            if(!stack.isEmpty()){
                stack.remove(stack.size()-1);
            } // else ignore leading ..
            continue;
        }
        stack.add(part);
    }
    // Process relative path
    for(String part: relativePath.split("/")){
        if(part.isEmpty() || part.equals(".")) continue;
        if(part.equals("..")){
            if(!stack.isEmpty()){
                stack.remove(stack.size()-1);
            } // else ignore leading ..
            continue;
        }
        stack.add(part);
    }
    // Build result
    StringBuilder sb = new StringBuilder();
    if(leadingSlash) sb.append("/");
    for(int i=0;i<stack.size();i++){
        sb.append(stack.get(i));
        if(i<stack.size()-1) sb.append("/");
    }
    return sb.toString();
}

