public boolean isExpired(long timestamp,long expiredThreshold){
    if (expiredThreshold == -1) {
        // -1 indicates the metrics never expire
        return false;
    }
    long now = System.currentTimeMillis();
    // If the timestamp is in the future, consider it not expired
    if (now < timestamp) {
        return false;
    }
    return now - timestamp > expiredThreshold;
}

