private void checkIfPackedField() throws IOException {
    // Determine the wire type of the current field tag.
    // Wire type 2 indicates a length-delimited field, which is used for packed repeated fields.
    final int WIRETYPE_LENGTH_DELIMITED = 2;
    int wireType = (this.tag & 0x7);

    // If the field is repeated and the wire type is length-delimited,
    // then we are reading a packed field.
    if (this.isRepeated && wireType == WIRETYPE_LENGTH_DELIMITED) {
        this.packed = true;
    } else {
        this.packed = false;
    }
