public int readTag() throws IOException {
    // Attempt to read a varint-encoded field tag from the buffer.
    // Return 0 if we have reached EOF or the buffer is exhausted.
    int tag = 0;
    int shift = 0;
    while (true) {
        if (pos == count) {
            // No more bytes available in the buffer; treat as EOF.
            return 0;
        }
        byte b = buf[pos++];
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break; // finished reading the varint
        }
        shift += 7;
        if (shift >= 32) {
            throw new IOException("Malformed varint in readTag");
        }
    }
    return tag;
}

int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        int b = read();   // read one byte from the underlying stream
        if (b == -1) {
            // EOF reached; return zero as per protocol specification
            return 0;
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    // If we get here, the varint was too large to fit in 32 bits
    throw new IOException("Malformed tag");
}

