}

private String buildContentRange() {
    // Build the Content-Range header value in the format:
    //   "bytes <start>-<end>/<total>"
    // where start, end and total represent the first byte,
    // the last byte (inclusive), and the total size of the resource.
    // If any of these values is unavailable, return null.
    if (startRange == null || endRange == null || totalContentLength == null) {
        return null;
    }
    return String.format("bytes %d-%d/%d", startRange, endRange, totalContentLength);
}

