public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> filtered = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile() || timeRanges == null || timeRanges.isEmpty()) {
        return filtered;
    }
    List<ThreadSnapshot> allSnapshots = null;
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
        Object obj = ois.readObject();
        @SuppressWarnings("unchecked")
        List<ThreadSnapshot> list = (obj instanceof List) ? (List<ThreadSnapshot>) obj : null;
        if (list != null) {
            allSnapshots = list;
        }
    } catch (ClassNotFoundException | ClassCastException e) {
        // If the file cannot be deserialized into a List of ThreadSnapshot, return empty list
        return filtered;
    }
    if (allSnapshots == null) {
        return filtered;
    }
    for (ThreadSnapshot ts : allSnapshots) {
        long timestamp = ts.getTimestamp(); // assume ThreadSnapshot has this method
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            long start = range.getStartMillis(); // assume this method
            long end = range.getEndMillis();     // assume this method
            if (timestamp >= start && timestamp <= end) {
                filtered.add(ts);
                break;
            }
        }
    }
    return filtered;
}

