    List<ThreadSnapshot> allSnapshots = new ArrayList<>();
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
        Object obj = ois.readObject();
        if (obj instanceof List<?>) {
            for (Object o : (List<?>) obj) {
                if (o instanceof ThreadSnapshot) {
                    allSnapshots.add((ThreadSnapshot) o);
                }
            }
        }
    } catch (ClassNotFoundException e) {
        // If the file cannot be deserialized into ThreadSnapshot objects, throw an IOException
        throw new IOException("Failed to deserialize thread snapshots from file", e);
    }

    // Filter snapshots by time ranges
    List<ThreadSnapshot> result = new ArrayList<>();
    for (ThreadSnapshot snapshot : allSnapshots) {
        long ts = snapshot.getTimestamp(); // assume getTimestamp() returns milliseconds
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (ts >= range.getStartTimeMillis() && ts <= range.getEndTimeMillis()) {
                result.add(snapshot);
                break;
            }
        }
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("Provided file is null or does not exist.");
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("Time ranges list must not be null.");
    }

    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            try {
                // Expected line format: <timestamp>,<threadName>,<stackTrace>
                String[] parts = line.split(",", 3);
                if (parts.length < 3) {
                    // Invalid format, skip this line
                    continue;
                }
                long timestamp = Long.parseLong(parts[0].trim());
                String threadName = parts[1].trim();
                String stackTrace = parts[2].trim();

                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, threadName, stackTrace);

                boolean inRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range == null) {
                        continue;
                    }
                    long start = range.getStartTime();
                    long end = range.getEndTime();
                    if (timestamp >= start && timestamp <= end) {
                        inRange = true;
                        break;
                    }
                }
                if (inRange) {
                    result.add(snapshot);
                }
            } catch (NumberFormatException nfe) {
                // Log and skip malformed line
                System.err.println("Skipping line due to parse error: " + line);
            } catch (IllegalArgumentException iae) {
                // Handle any constructor related errors
                System.err.println("Skipping line due to constructor error: " + line);
            }
        }
    } catch (IOException ioe) {
        // Propagate IO exceptions as declared
        throw ioe;
    }
    return result;
}
